package com.bank.mapping.legacy;

import java.util.HashMap;
import java.util.Map;
import java.util.logging.Logger;

// Models the OLD behaviour: multiple types share ONE underlying field space.
// Adding the same field name with a different type across "types" conflicts.
public class SharedIndex {
    private static final Logger log = Logger.getLogger(SharedIndex.class.getName());
    // field name -> its single, shared Lucene field type
    private final Map<String, String> sharedFields = new HashMap<>();

    // 'mappingType' is the legacy type name (e.g. "customer", "transaction").
    public void defineField(String mappingType, String field, String fieldType) {
        String existing = sharedFields.get(field);
        if (existing != null && !existing.equals(fieldType)) {
            // All types share one Lucene field -> irreconcilable conflict.
            throw new IllegalStateException(
                "mapping conflict: field '" + field + "' already defined as '" + existing
                + "' (by another type) but type '" + mappingType + "' wants '" + fieldType + "'");
        }
        sharedFields.put(field, fieldType);
        log.info(() -> "type '" + mappingType + "' defined field '" + field + "' as " + fieldType);
    }
}
