package com.bank.mapping.modern;

import java.util.HashMap;
import java.util.Map;

// Modern model: one index, one implicit type (_doc), its own field space.
public class IndexDefinition {
    public static final String TYPE = "_doc"; // fixed, implicit type
    private final String name;
    private final Map<String, String> fields = new HashMap<>();

    public IndexDefinition(String name) { this.name = name; }

    // No cross-type sharing: this index owns its fields completely.
    public void defineField(String field, String fieldType) {
        fields.put(field, fieldType);
    }

    public String getName() { return name; }
    public Map<String, String> getFields() { return fields; }
}
