package com.bank.mapping.modern;

import java.util.LinkedHashMap;
import java.util.Map;
import java.util.logging.Logger;

// Holds independent indices. Two entities = two indices, no field sharing.
public class IndexCatalog {
    private static final Logger log = Logger.getLogger(IndexCatalog.class.getName());
    private final Map<String, IndexDefinition> indices = new LinkedHashMap<>();

    public IndexDefinition createIndex(String name) {
        IndexDefinition def = new IndexDefinition(name);
        indices.put(name, def);
        log.info(() -> "created index '" + name + "' with type " + IndexDefinition.TYPE);
        return def;
    }

    public void describe() {
        indices.values().forEach(idx ->
            log.info(() -> "index '" + idx.getName() + "' (type=" + IndexDefinition.TYPE
                    + ") fields=" + idx.getFields()));
    }
}
