package com.bank.mapping;

import com.bank.mapping.legacy.SharedIndex;
import com.bank.mapping.modern.IndexCatalog;
import com.bank.mapping.modern.IndexDefinition;
import java.util.logging.Level;
import java.util.logging.Logger;

public class MappingDemo {
    private static final Logger log = Logger.getLogger(MappingDemo.class.getName());

    public static void main(String[] args) {
        // --- OLD model: two types in one index collide on field "amount" ---
        log.info("=== legacy multi-type index ===");
        SharedIndex shared = new SharedIndex();
        shared.defineField("customer", "amount", "long");   // credit limit as number
        try {
            shared.defineField("transaction", "amount", "text"); // money as text -> CONFLICT
        } catch (IllegalStateException e) {
            log.log(Level.SEVERE, "legacy design failed: " + e.getMessage(), e);
        }

        // --- MODERN model: two independent indices, both type _doc ---
        log.info("=== modern single-type design ===");
        IndexCatalog catalog = new IndexCatalog();
        IndexDefinition customers = catalog.createIndex("customers");
        customers.defineField("amount", "long");            // credit limit

        IndexDefinition transactions = catalog.createIndex("transactions");
        transactions.defineField("amount", "scaled_float");  // money, no clash

        catalog.describe();
    }
}
